import { createServer as createHttpServer } from 'node:http'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const MAX_TEXT_BYTES = 10000

const publicDir = join(dirname(fileURLToPath(import.meta.url)), 'public')

// Explicit asset map rather than a path-resolving static handler: no traversal
// surface, and adding a file is one deliberate line here.
const ASSETS = {
  '/': { file: join(publicDir, 'index.html'), type: 'text/html; charset=utf-8' },
  '/styles.css': { file: join(publicDir, 'styles.css'), type: 'text/css; charset=utf-8' },
  '/app.js': { file: join(publicDir, 'app.js'), type: 'text/javascript; charset=utf-8' },
}

function send(res, status, payload, headers = {}) {
  const body = JSON.stringify(payload)
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(body),
    ...headers,
  })
  res.end(body)
}

// Resolves to the body text, or null once the body exceeds MAX_TEXT_BYTES.
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let received = 0
    let tooLarge = false
    req.on('data', (chunk) => {
      if (tooLarge) return
      received += chunk.length
      if (received > MAX_TEXT_BYTES) {
        tooLarge = true
        chunks.length = 0
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')))
    req.on('error', reject)
  })
}

export function createServer(store) {
  const assets = new Map(
    Object.entries(ASSETS).map(([route, asset]) => [route, { type: asset.type, body: readFileSync(asset.file) }]),
  )

  async function handleTextPut(req, res) {
    const body = await readBody(req)
    if (body === null) return send(res, 413, { error: 'text too long' })

    let parsed
    try {
      parsed = JSON.parse(body)
    } catch {
      return send(res, 400, { error: 'text must be a string' })
    }
    if (typeof parsed?.text !== 'string') return send(res, 400, { error: 'text must be a string' })

    store.write(parsed.text)
    send(res, 200, { text: parsed.text })
  }

  return createHttpServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname
      if (req.method !== 'GET' && req.method !== 'PUT') {
        return send(res, 405, { error: 'method not allowed' }, { allow: 'GET, PUT' })
      }

      if (pathname === '/api/text') {
        if (req.method === 'GET') return send(res, 200, { text: store.read() })
        return await handleTextPut(req, res)
      }

      const asset = assets.get(pathname)
      if (!asset) return send(res, 404, { error: 'not found' })
      if (req.method !== 'GET') return send(res, 405, { error: 'method not allowed' }, { allow: 'GET' })

      res.writeHead(200, {
        'content-type': asset.type,
        'content-length': asset.body.length,
      })
      res.end(asset.body)
    } catch (error) {
      console.error(`${req.method} ${req.url} failed:`, error)
      if (!res.headersSent) send(res, 500, { error: 'internal' })
      else res.destroy(error)
    }
  })
}

import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs'
import { dirname } from 'node:path'

export const DEFAULT_TEXT = 'hello world'

/**
 * The only module in this codebase that touches the filesystem.
 * The file holds the greeting as UTF-8 text.
 */
export function createFileStore(filePath) {
  function read() {
    try {
      return readFileSync(filePath, 'utf8')
    } catch (error) {
      if (error.code === 'ENOENT') return DEFAULT_TEXT
      throw error
    }
  }

  function write(text) {
    if (typeof text !== 'string') {
      throw new TypeError('text must be a string')
    }
    mkdirSync(dirname(filePath), { recursive: true })
    // Temp file + rename: a crash mid-write cannot leave hello.json truncated.
    const tempPath = `${filePath}.tmp`
    writeFileSync(tempPath, text, 'utf8')
    renameSync(tempPath, filePath)
  }

  return { read, write }
}

const el = document.querySelector('#text')
const statusEl = document.querySelector('#status')

const DEBOUNCE_MS = 400
const PULSE_MS = 1200

let debounceTimer = null
let pulseTimer = null
let pending = false
let editVersion = 0

function setStatus(message, state) {
  statusEl.textContent = message
  statusEl.classList.remove('saving', 'saved', 'error')
  if (state) statusEl.classList.add(state)
}

function stamp() {
  const now = new Date()
  const hours = String(now.getHours()).padStart(2, '0')
  const minutes = String(now.getMinutes()).padStart(2, '0')
  return `${hours}:${minutes}`
}

function pulse() {
  for (const node of [statusEl, el]) node.classList.add('saved')
  clearTimeout(pulseTimer)
  pulseTimer = setTimeout(() => {
    for (const node of [statusEl, el]) node.classList.remove('saved')
  }, PULSE_MS)
}

async function save({ keepalive = false } = {}) {
  clearTimeout(debounceTimer)
  debounceTimer = null
  if (!pending) return
  const savingVersion = editVersion
  const text = el.textContent

  try {
    const res = await fetch('/api/text', {
      method: 'PUT',
      body: JSON.stringify({ text }),
      keepalive,
    })
    if (!res.ok) throw new Error(`PUT /api/text responded ${res.status}`)
    if (editVersion === savingVersion) {
      pending = false
      setStatus(`Saved ${stamp()}`, 'saved')
      pulse()
    }
  } catch (error) {
    console.error('Could not save the greeting:', error)
    if (editVersion === savingVersion && pending) {
      setStatus('Not saved — will retry', 'error')
    }
  }
}

function scheduleSave() {
  pending = true
  editVersion += 1
  setStatus('Saving…', 'saving')
  clearTimeout(debounceTimer)
  debounceTimer = setTimeout(save, DEBOUNCE_MS)
}

el.addEventListener('input', scheduleSave)
el.addEventListener('keydown', (event) => {
  // The greeting is a single line; Enter would inject <div>/<br> nodes.
  if (event.key === 'Enter') event.preventDefault()
})
el.addEventListener('blur', () => {
  if (pending) save({ keepalive: true })
})
window.addEventListener('pagehide', () => {
  if (pending) save({ keepalive: true })
})

const loadingVersion = editVersion
try {
  const res = await fetch('/api/text')
  if (!res.ok) throw new Error(`GET /api/text responded ${res.status}`)
  const { text } = await res.json()
  if (editVersion === loadingVersion) {
    el.textContent = text
    setStatus('Type to edit')
  }
} catch (error) {
  console.error('Could not load the greeting:', error)
  if (editVersion === loadingVersion) {
    setStatus('Not loaded — showing default', 'error')
  }
}

import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createFileStore } from './store.js'
import { createServer } from './server.js'

const root = dirname(fileURLToPath(import.meta.url))
const portValue = process.env.PORT ?? '3000'
const port = Number(portValue)
if (!/^\d+$/.test(portValue) || !Number.isInteger(port) || port < 1 || port > 65535) {
  throw new RangeError('PORT must be an integer from 1 to 65535')
}
const dataFile = process.env.DATA_FILE ? resolve(process.env.DATA_FILE) : join(root, 'data', 'hello.json')

createServer(createFileStore(dataFile)).listen(port, () => {
  console.log(`Editing at http://localhost:${port}  (data: ${dataFile})`)
})

import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, rmSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { connect } from 'node:net'
import { join } from 'node:path'
import { createServer } from '../server.js'
import { createFileStore } from '../store.js'

let dir
let dataFile
let server
let base

function startStore(store) {
  return new Promise((resolve) => {
    const s = createServer(store)
    s.listen(0, () => {
      s.base = `http://127.0.0.1:${s.address().port}`
      resolve(s)
    })
  })
}

function start(file) {
  return startStore(createFileStore(file))
}

function requestRaw(port, request) {
  return new Promise((resolve, reject) => {
    const socket = connect(port, '127.0.0.1', () => socket.end(request))
    let response = ''
    socket.setEncoding('utf8')
    socket.on('data', (chunk) => {
      response += chunk
    })
    socket.on('end', () => resolve(response))
    socket.on('error', reject)
  })
}

async function captureConsoleError(fn) {
  const original = console.error
  const calls = []
  console.error = (...args) => calls.push(args)
  try {
    await fn(calls)
  } finally {
    console.error = original
  }
}

function close(s) {
  return new Promise((resolve, reject) => s.close((error) => (error ? reject(error) : resolve())))
}

before(async () => {
  dir = mkdtempSync(join(tmpdir(), 'hello-api-'))
  dataFile = join(dir, 'hello.json')
  server = await start(dataFile)
  base = server.base
})

after(async () => {
  await close(server)
  rmSync(dir, { recursive: true, force: true })
})

test('GET / serves HTML with a contenteditable headline', async () => {
  const res = await fetch(`${base}/`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^text\/html/)
  assert.match(await res.text(), /contenteditable/)
})

test('GET /api/text returns the default text on a fresh store', async () => {
  const res = await fetch(`${base}/api/text`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { text: 'hello world' })
})

test('PUT /api/text stores the new text', async () => {
  const put = await fetch(`${base}/api/text`, {
    method: 'PUT',
    body: JSON.stringify({ text: 'hi there' }),
  })
  assert.equal(put.status, 200)
  assert.deepEqual(await put.json(), { text: 'hi there' })

  const get = await fetch(`${base}/api/text`)
  assert.deepEqual(await get.json(), { text: 'hi there' })
})

test('text survives a server restart over the same file', async () => {
  await close(server)

  server = await start(dataFile)
  base = server.base

  const res = await fetch(`${base}/api/text`)
  assert.deepEqual(await res.json(), { text: 'hi there' })
  assert.match(readFileSync(dataFile, 'utf8'), /hi there/)
})

test('PUT with a non-string text is 400', async () => {
  const res = await fetch(`${base}/api/text`, { method: 'PUT', body: JSON.stringify({ text: 123 }) })
  assert.equal(res.status, 400)
  assert.ok((await res.json()).error)
})

test('PUT with an unparseable body is 400', async () => {
  const res = await fetch(`${base}/api/text`, { method: 'PUT', body: 'not json' })
  assert.equal(res.status, 400)
  assert.ok((await res.json()).error)
})

test('PUT with an oversized body is 413', async () => {
  const res = await fetch(`${base}/api/text`, {
    method: 'PUT',
    body: JSON.stringify({ text: 'a'.repeat(10001) }),
  })
  assert.equal(res.status, 413)
  assert.deepEqual(await res.json(), { error: 'text too long' })
})

test('DELETE /api/text is 405 with an Allow header', async () => {
  const res = await fetch(`${base}/api/text`, { method: 'DELETE' })
  assert.equal(res.status, 405)
  assert.match(res.headers.get('allow'), /GET/)
})

test('GET /nope is 404', async () => {
  const res = await fetch(`${base}/nope`)
  assert.equal(res.status, 404)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('a malformed request target returns 500 without stopping the server', async () => {
  await captureConsoleError(async (errors) => {
    const response = await requestRaw(
      server.address().port,
      'GET http:// HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n',
    )
    assert.match(response, /^HTTP\/1\.1 500 /)
    assert.match(response, /\{"error":"internal"\}/)
    assert.match(errors[0][0], /GET http:\/\/ failed:/)
  })

  const res = await fetch(`${base}/api/text`)
  assert.equal(res.status, 200)
})

test('store failures return 500 and log the request context', async () => {
  const failure = new Error('disk unavailable')
  const failingServer = await startStore({
    read() {
      throw failure
    },
    write() {
      throw failure
    },
  })

  try {
    await captureConsoleError(async (errors) => {
      const get = await fetch(`${failingServer.base}/api/text`)
      assert.equal(get.status, 500)
      assert.deepEqual(await get.json(), { error: 'internal' })

      const put = await fetch(`${failingServer.base}/api/text`, {
        method: 'PUT',
        body: JSON.stringify({ text: 'hello' }),
      })
      assert.equal(put.status, 500)
      assert.deepEqual(await put.json(), { error: 'internal' })

      assert.equal(errors.length, 2)
      assert.match(errors[0][0], /GET \/api\/text failed:/)
      assert.equal(errors[0][1], failure)
      assert.match(errors[1][0], /PUT \/api\/text failed:/)
      assert.equal(errors[1][1], failure)
    })
  } finally {
    await close(failingServer)
  }
})

test('GET /styles.css and /app.js serve their assets', async () => {
  const css = await fetch(`${base}/styles.css`)
  assert.equal(css.status, 200)
  assert.match(css.headers.get('content-type'), /^text\/css/)

  const js = await fetch(`${base}/app.js`)
  assert.equal(js.status, 200)
  assert.match(js.headers.get('content-type'), /^text\/javascript/)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createFileStore, DEFAULT_TEXT } from '../store.js'

function withTempDir(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'hello-'))
  try {
    return fn(dir)
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
}

test('DEFAULT_TEXT is "hello world"', () => {
  assert.equal(DEFAULT_TEXT, 'hello world')
})

test('read() returns the default text when no file exists', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.equal(store.read(), 'hello world')
  })
})

test('write() then a new store instance reads the persisted text', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    createFileStore(file).write('bonjour')
    assert.equal(readFileSync(file, 'utf8'), 'bonjour')
    assert.equal(createFileStore(file).read(), 'bonjour')
  })
})

test('read() returns a file\'s raw text', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    writeFileSync(file, 'legacy greeting')
    assert.equal(createFileStore(file).read(), 'legacy greeting')
  })
})

test('unicode and newlines round-trip byte-for-byte', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    const text = 'héllo 🌍\nline2'
    createFileStore(file).write(text)
    assert.equal(createFileStore(file).read(), text)
  })
})

test('write() creates missing parent directories', () => {
  withTempDir((dir) => {
    const file = join(dir, 'data', 'nested', 'x.json')
    const store = createFileStore(file)
    store.write('deep')
    assert.equal(store.read(), 'deep')
  })
})

test('read() propagates a real IO error instead of returning the default', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.read())
  })
})

test('write() rejects non-string input with a TypeError', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.throws(() => store.write(42), TypeError)
    assert.equal(store.read(), 'hello world')
  })
})

test('mkdirSync failures during write propagate', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.write('x'))
  })
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')

for (const value of ['', 'abc', '65536']) {
  test(`PORT=${JSON.stringify(value)} is rejected clearly`, () => {
    const result = spawnSync(process.execPath, ['main.js'], {
      cwd: root,
      env: { ...process.env, PORT: value },
      encoding: 'utf8',
    })

    assert.notEqual(result.status, 0)
    assert.match(result.stderr, /PORT must be an integer from 1 to 65535/)
  })
}

